{
  "items": [
    {
      "name": "Set.Finite.infinite_compl",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} [Infinite α] {s : Set α}, s.Finite → sᶜ.Infinite"
    },
    {
      "name": "Set.Infinite.diff",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {s t : Set α}, s.Infinite → t.Finite → (s \\ t).Infinite"
    },
    {
      "name": "Set.infinite_image_iff",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {s : Set α} {f : α → β}, Set.InjOn f s → ((f '' s).Infinite ↔ s.Infinite)"
    },
    {
      "name": "Cardinal.mk_compl_finset_of_infinite",
      "module_name": "Mathlib.SetTheory.Cardinal.Arithmetic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [Infinite α] (s : Finset α), Cardinal.mk ↑(↑s)ᶜ = Cardinal.mk α"
    },
    {
      "name": "Set.infinite_of_injOn_mapsTo",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {s : Set α} {t : Set β} {f : α → β},\n  Set.InjOn f s → Set.MapsTo f s t → s.Infinite → t.Infinite"
    },
    {
      "name": "Infinite.of_injective",
      "module_name": "Mathlib.Data.Fintype.EquivFin",
      "kind": "theorem",
      "type": "∀ {α : Sort u_4} {β : Sort u_5} [Infinite β] (f : β → α), Function.Injective f → Infinite α"
    },
    {
      "name": "Set.not_injOn_infinite_finite_image",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {f : α → β} {s : Set α}, s.Infinite → (f '' s).Finite → ¬Set.InjOn f s"
    },
    {
      "name": "Set.infinite_range_of_injective",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [Infinite α] {f : α → β}, Function.Injective f → (Set.range f).Infinite"
    }
  ]
}
